419		// 子集匹配：zone=x 同时匹配带 host 额外标签和无额外标签的两条序列；
420		// 排序沿用 snapshot：标签对 (host,h)<(zone,x)，故带 host 的序列在前。
421		res = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":2,"labels":{"zone":"x"}}`)
422		if len(res.Series) != 2 || res.Series[0].Average != 4 || res.Series[1].Average != 3 {
423			t.Fatalf("subset match = %+v, want averages 4 and 3", res.Series)
