18	// labelsOf 按指标名与完整标签集合在写入快照中定位序列，返回其标签与采样点。
19	func labelsOf(t *testing.T, res *BatchResult, name string, labels map[string]string) (map[string]string, []Point) {
20		t.Helper()
21		i := findViewIndex(t, res, name, labels)
22		return res.Series[i].Labels, res.Series[i].Points
