25	// queryOne 要求查询恰好命中一个序列并返回该条目。
26	func queryOne(t *testing.T, store *MetricStore, line string) QuerySeries {
27		t.Helper()
28		res := mustQuery(t, store, line)
29		if len(res.Series) != 1 {
30			t.Fatalf("query %s: got %d series %+v, want exactly 1", line, len(res.Series), res.Series)
31		}
