35	// sample 构造一条采样点 JSON 文本；labels 为 nil 时省略 labels 字段。
36	// 名称与标签经 encoding/json 转义，因此调用方可以直接给含分隔字符与空格的原始文本。
37	func sample(name string, ts int64, value any, labels map[string]string) string {
38		var b strings.Builder
39		n, _ := json.Marshal(name)
40		fmt.Fprintf(&b, `{"name":%s,"timestamp":%d,"value":%v`, n, ts, value)
41		if labels != nil {
42			b.WriteString(`,"labels":`)
43			b.WriteString(jsonLabels(labels))
44		}
45		b.WriteByte('}')
46		return b.String()
47	}
