49	// jsonLabels 把标签集合编码为 JSON 对象文本（Go 按键排序输出，身份与顺序无关）。
50	func jsonLabels(labels map[string]string) string {
51		b, _ := json.Marshal(labels)
52		return string(b)
53	}
54	
55	// jsonString 把单个字符串编码为 JSON 字符串文本。
56	func jsonString(s string) string {
57		b, _ := json.Marshal(s)
58		return string(b)
59	}
