61	// uescape 返回 JSON 的 \uXXXX 转义文本（反斜杠以 rune 构造，避免与源码转义混淆）。
62	func uescape(hex string) string {
63		return string(rune(92)) + "u" + hex
64	}
65	
66	// withJSONEscapes 把模板中的占位符替换为对应字符的 JSON \uXXXX 转义书写，
67	// 用于以“转义写法”提交与直接书写完全相同的真实文本。
68	func withJSONEscapes(tmpl string) string {
69		return strings.NewReplacer(
70			"#CO#", uescape("003a"), // ':'
71			"#SC#", uescape("003b"), // ';'
72			"#LB#", uescape("007b"), // '{'
73			"#RB#", uescape("007d"), // '}'
74		).Replace(tmpl)
75	}
