77	// queryLabels 构造按标签子集查询的 JSON 对象文本。
78	func queryLabels(name string, start, end int64, labels map[string]string) string {
79		return `{"op":"query","name":` + jsonString(name) +
80			fmt.Sprintf(`,"start":%d,"end":%d,"labels":`, start, end) + jsonLabels(labels) + `}`
81	}
