83	// TestDelimitersInLabelValueStayDistinct 是核心回归：一个标签值看起来像另外两个
84	// 标签（"b=2"），另一个标签值看起来包含标签对分隔符（"b=2,c=3"）。冒号、分号、
85	// 等号、逗号和花括号在值里都是普通字符，不能被当成键值或标签之间的边界。
86	func TestDelimitersInLabelValueStayDistinct(t *testing.T) {
87		store := NewMetricStore()
88		// 三条序列在同一时间戳写入相同数值 1，但完整标签集合不同，必须分别新增。
89		// single:  一个标签，其值文本上像 "b=2"。
90		// pair:    两个标签，文本拼起来恰好也是 a=1,b=2。
91		// spill:   一个标签，其值文本上像两个标签 "b=2,c=3"。
92		res := mustOK(t, store, `[
93			{"name":"m","timestamp":10,"value":1,"labels":{"a":"b=2"}},
94			{"name":"m","timestamp":10,"value":1,"labels":{"a":"1","b":"2"}},
95			{"name":"m","timestamp":10,"value":1,"labels":{"a":"b=2,c=3"}}
96		]`)
97		if res.Added != 3 || res.Duplicates != 0 || len(res.Series) != 3 {
98			t.Fatalf("look-alike label text must create 3 series, got %+v", res)
99		}
100	
101		// 成功结果保留各自完整的名称、标签与采样点（值里的等号/逗号原样保留）。
102		single := map[string]string{"a": "b=2"}
103		pair := map[string]string{"a": "1", "b": "2"}
104		spill := map[string]string{"a": "b=2,c=3"}
105		for _, want := range []struct {
106			labels map[string]string
107			point  Point
108		}{
109			{single, Point{Timestamp: 10, Value: 1}},
110			{pair, Point{Timestamp: 10, Value: 1}},
111			{spill, Point{Timestamp: 10, Value: 1}},
112		} {
113			gotLabels, gotPoints := labelsOf(t, res, "m", want.labels)
114			if !reflect.DeepEqual(gotLabels, want.labels) {
115				t.Fatalf("labels not preserved verbatim: got %v want %v", gotLabels, want.labels)
116			}
117			if len(gotPoints) != 1 || gotPoints[0] != want.point {
118				t.Fatalf("points for %v = %+v, want %+v", want.labels, gotPoints, want.point)
119			}
120		}
121	
122		// 子集查询各匹配各的序列：标签文本里的 "b=2" 片段不能被当成另一个标签 b。
123		if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"a":"b=2"}}`); !reflect.DeepEqual(got.Labels, single) || got.Count != 1 || got.Average != 1 {
124			t.Fatalf("a=b=2 query = %+v, want the single-label series", got)
125		}
126		if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"b":"2"}}`); !reflect.DeepEqual(got.Labels, pair) || got.Count != 1 {
127			t.Fatalf("b=2 subset must match only the real two-label series, got %+v", got)
128		}
129		if len(mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"c":"3"}}`).Series) != 0 {
130			t.Fatalf("value fragment c=3 must not be read as a label")
131		}
132		// 全量查询仍是三条独立序列，各自一个点，点数与均值互不混淆。
133		all := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
134		if len(all.Series) != 3 {
135			t.Fatalf("full query = %+v, want 3 separate series", all.Series)
136		}
137		for _, s := range all.Series {
138			if s.Count != 1 || s.Average != 1 {
139				t.Fatalf("series %v must keep its own single point, got count=%d average=%v", s.Labels, s.Count, s.Average)
140			}
141		}
142	
143		// 三条序列写入彼此不同的数值也不冲突；各序列各取自己的均值。
144		mustOK(t, store, `[{"name":"m","timestamp":20,"value":5,"labels":{"a":"b=2"}}]`)
145		mustOK(t, store, `[{"name":"m","timestamp":20,"value":7,"labels":{"a":"1","b":"2"}}]`)
146		mustOK(t, store, `[{"name":"m","timestamp":20,"value":9,"labels":{"a":"b=2,c=3"}}]`)
147		if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"a":"b=2"}}`); got.Count != 2 || got.Average != 3 {
148			t.Fatalf("single series average = count %d avg %v, want 2 points avg 3", got.Count, got.Average)
149		}
150		if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"a":"1","b":"2"}}`); got.Count != 2 || got.Average != 4 {
151			t.Fatalf("pair series average = count %d avg %v, want 2 points avg 4", got.Count, got.Average)
152		}
153		if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"a":"b=2,c=3"}}`); got.Count != 2 || got.Average != 5 {
154			t.Fatalf("spill series average = count %d avg %v, want 2 points avg 5", got.Count, got.Average)
155		}
156	}
