158	// TestDelimitersAcrossKeysValuesAndNames 把全部分隔字符放进标签键与标签值，
159	// 并让指标名本身也含分隔字符；任何字符都不得充当边界导致身份合并。
160	func TestDelimitersAcrossKeysValuesAndNames(t *testing.T) {
161		store := NewMetricStore()
162		tricky := []string{":", ";", "=", ",", "{", "}", "{=", "=}", ",;", ":=;{}", "x{y=z,w}"}
163		batch := make([]string, 0, 2*len(tricky)+2)
164		// 同名、标签键含分隔字符：每个键一条独立序列。
165		for i, k := range tricky {
166			batch = append(batch, sample("cpu", 100, i+1, map[string]string{k: "plain"}))
167		}
168		// 标签值含分隔字符的一组。
169		for i, v := range tricky {
170			batch = append(batch, sample("cpu", 100, i+100, map[string]string{"k": v}))
171		}
172		// 指标名含分隔字符，与名为 cpu 的序列区分开。
173		batch = append(batch,
174			sample("cpu:rate{host=a}", 100, 7, nil),
175			sample("cpu:rate{host=a", 100, 8, nil), // 少一个花括号也是另一个名字
176		)
177		res := mustOK(t, store, "["+strings.Join(batch, ",")+"]")
178		if want := 2*len(tricky) + 2; res.Added != want || len(res.Series) != want {
179			t.Fatalf("delimiter-heavy identities: added=%d series=%d, want %d", res.Added, len(res.Series), want)
180		}
181	
182		// 键含分号/冒号的标签仍能精确子集查询。
183		for _, k := range tricky {
184			line := queryLabels("cpu", 0, 200, map[string]string{k: "plain"})
185			got := queryOne(t, store, line)
186			if v, ok := got.Labels[k]; !ok || v != "plain" || len(got.Labels) != 1 {
187				t.Fatalf("delimiter key %q not matched verbatim: %+v", k, got)
188			}
189		}
190		// 值含花括号/逗号等的标签同样原样匹配。
191		got := queryOne(t, store, queryLabels("cpu", 0, 200, map[string]string{"k": "x{y=z,w}"}))
192		if got.Labels["k"] != "x{y=z,w}" || got.Average != float64(100+len(tricky)-1) {
193			t.Fatalf("delimiter value not preserved/matched: %+v", got)
194		}
195		// 指标名中的分隔字符是名字的一部分：两个花括号形态不同的名字各自独立。
196		for _, c := range []struct {
197			name string
198			val  float64
199		}{
200			{"cpu:rate{host=a}", 7},
201			{"cpu:rate{host=a", 8},
202		} {
203			line := `{"op":"query","name":` + jsonString(c.name) + `,"start":0,"end":200}`
204			s := queryOne(t, store, line)
205			if s.Name != c.name || s.Average != c.val || len(s.Labels) != 0 {
206				t.Fatalf("delimiter-in-name query = %+v, want name %q value %v", s, c.name, c.val)
207			}
208		}
209	}
