266	// TestDelimiterIdentityDuplicateAcrossOrderAndEscapes：身份确实相同时，调换标签
267	// 书写顺序、用合法 JSON 转义书写同一个分隔字符，再次提交相同时间戳与数值都计为
268	// 重复，不新增点；成功结果里字符仍是解析后的真实文本（只有一个真实冒号）。
269	func TestDelimiterIdentityDuplicateAcrossOrderAndEscapes(t *testing.T) {
270		store := NewMetricStore()
271		mustOK(t, store, `[{"name":"m:x","timestamp":5,"value":4,"labels":{"a:1":"x;y","b":"{z}"}}]`)
272		// 标签顺序调换；名字里的冒号、键里的冒号、值里的分号与花括号改用 JSON
273		// #XX# 占位符对应的 \uXXXX 转义书写，解析后的真实文本必须与首条完全一致。
274		resubmit := withJSONEscapes(
275			`[{"name":"m#CO#x","timestamp":5,"value":4.0,"labels":{"b":"#LB#z#RB#","a#CO#1":"x#SC#y"}}]`)
276		res := mustOK(t, store, resubmit)
277		if res.Added != 0 || res.Duplicates != 1 || len(res.Series) != 1 {
278			t.Fatalf("escaped/reordered resubmit must be one duplicate, got %+v", res)
279		}
280		got := res.Series[0]
281		wantLabels := map[string]string{"a:1": "x;y", "b": "{z}"}
282		if got.Name != "m:x" || !reflect.DeepEqual(got.Labels, wantLabels) {
283			t.Fatalf("identity must resolve to parsed text, got name=%q labels=%v", got.Name, got.Labels)
284		}
285		if pts := got.Points; len(pts) != 1 || pts[0] != (Point{Timestamp: 5, Value: 4}) {
286			t.Fatalf("duplicate must add no point, got %+v", pts)
287		}
288	
289		// 同一时间戳换成不同数值（同样以转义+乱序书写身份）：拒绝整批，冲突指向
290		// JSON 解析后的真实完整序列、时间戳以及已有值与提交值。
291		conflictLine := withJSONEscapes(
292			`[{"name":"m#CO#x","timestamp":5,"value":40,"labels":{"b":"#LB#z#RB#","a#CO#1":"x#SC#y"}}]`)
293		lerr := mustFail(t, store, conflictLine)
294		if lerr.Index != 1 || lerr.Conflict == nil {
295			t.Fatalf("expected conflict, got %+v", lerr)
296		}
297		c := lerr.Conflict
298		if c.Series.Name != "m:x" || !reflect.DeepEqual(c.Series.Labels, wantLabels) ||
299			c.Timestamp != 5 || c.Existing != 4 || c.Submitted != 40 {
300			t.Fatalf("conflict must name real identity/values, got %+v", c)
301		}
302		// 冲突原因文本里的序列按 name{k=v,...} 呈现，标签按键排序；含分隔字符的
303		// 名称、键或值以带引号形式呈现，内容字符与标签边界可区分（值 "{z}" 含花括号，
304		// 因此渲染为 "{z}"）。文本与结构化 conflict.series 指向同一真实身份。
305		if !strings.HasPrefix(lerr.Error, `conflict: series m:x{a:1=x;y,b="{z}"} at timestamp 5 already has value 4, submitted 40`) {
306			t.Fatalf("conflict message = %q", lerr.Error)
307		}
308		// 原采样点保持不变。
309		snap := mustOK(t, store, `[]`)
310		if pts := snap.Series[0].Points; len(pts) != 1 || pts[0].Value != 4 {
311			t.Fatalf("rejected batch must leave original point intact, got %+v", pts)
312		}
313	}
