315	// TestLookAlikeIdentitiesDoNotConflict：两条朴素文本渲染会撞车的不同序列，在同一
316	// 时间戳分别提交不同数值不得互相冲突；随后对其中一条再改值才冲突，且冲突报告的
317	// 是结构化的真实完整标签集合，冲突原因文本也把两条序列渲染成可区分的身份。
318	func TestLookAlikeIdentitiesDoNotConflict(t *testing.T) {
319		store := NewMetricStore()
320		mustOK(t, store, `[{"name":"cpu","timestamp":1,"value":1,"labels":{"a":"b=2"}}]`)
321		// 单标签 a="b=2" 与两标签 a=1,b=2 身份不同：不同值各自新增，互不冲突。
322		res := mustOK(t, store, `[{"name":"cpu","timestamp":1,"value":2,"labels":{"a":"1","b":"2"}}]`)
323		if res.Added != 1 || res.Duplicates != 0 || len(res.Series) != 2 {
324			t.Fatalf("look-alike identities with different values must both be added, got %+v", res)
325		}
326		// 对单标签序列提交不同值：冲突，结构化标签只有一个键且值原样为 "b=2"；
327		// 原因文本把含等号的值加引号渲染，与两标签序列的 cpu{a=1,b=2} 可区分。
328		lerr := mustFail(t, store, `[{"name":"cpu","timestamp":1,"value":9,"labels":{"a":"b=2"}}]`)
329		if lerr.Conflict == nil || lerr.Conflict.Existing != 1 || lerr.Conflict.Submitted != 9 {
330			t.Fatalf("single-label conflict values wrong: %+v", lerr.Conflict)
331		}
332		if labels := lerr.Conflict.Series.Labels; len(labels) != 1 || labels["a"] != "b=2" {
333			t.Fatalf("conflict must name real single-label identity, got %v", labels)
334		}
335		if !strings.Contains(lerr.Error, `series cpu{a="b=2"} at timestamp 1 already has value 1, submitted 9`) {
336			t.Fatalf("single-label conflict message = %q", lerr.Error)
337		}
338		// 对两标签序列提交不同值同样冲突，结构化标签是两个键，
339		// 原因文本渲染为不带引号的 cpu{a=1,b=2}，与单标签序列明确不同。
340		lerr = mustFail(t, store, `[{"name":"cpu","timestamp":1,"value":9,"labels":{"a":"1","b":"2"}}]`)
341		if lerr.Conflict == nil || lerr.Conflict.Existing != 2 {
342			t.Fatalf("two-label conflict values wrong: %+v", lerr.Conflict)
343		}
344		if labels := lerr.Conflict.Series.Labels; len(labels) != 2 || labels["a"] != "1" || labels["b"] != "2" {
345			t.Fatalf("conflict must name real two-label identity, got %v", labels)
346		}
347		if !strings.Contains(lerr.Error, `series cpu{a=1,b=2} at timestamp 1 already has value 2, submitted 9`) {
348			t.Fatalf("two-label conflict message = %q", lerr.Error)
349		}
350		// 两条序列原有采样点都保持各自的值，全量查询仍返回两条独立序列。
351		full := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":10}`)
352		if len(full.Series) != 2 {
353			t.Fatalf("full cpu query = %+v, want 2 series", full.Series)
354		}
355		for _, s := range full.Series {
356			if s.Count != 1 {
357				t.Fatalf("series %v must keep its own point, got count=%d", s.Labels, s.Count)
358			}
359		}
360	}
361	
362	// TestWhitespaceInIdentityPreservedVerbatim：名称、标签键和值中的合法空格原样
363	// 保留，不能通过去空格把不同输入合并为同一序列。
364	func TestWhitespaceInIdentityPreservedVerbatim(t *testing.T) {
365		store := NewMetricStore()
366		res := mustOK(t, store, `[
367			{"name":"m ","timestamp":1,"value":1,"labels":{"k ":"v"}},
368			{"name":"m","timestamp":1,"value":2,"labels":{"k":"v"}},
369			{"name":"m","timestamp":1,"value":3,"labels":{"k":" v"}},
370			{"name":"m","timestamp":1,"value":4,"labels":{"k":"v "}},
371			{"name":"m","timestamp":1,"value":5,"labels":{" k":"v"}}
372		]`)
373		if res.Added != 5 || len(res.Series) != 5 {
374			t.Fatalf("whitespace variants must be 5 distinct series, got added=%d series=%d", res.Added, len(res.Series))
375		}
376		cases := []struct {
377			name   string
378			labels map[string]string
379			value  float64
380		}{
381			{"m ", map[string]string{"k ": "v"}, 1},
382			{"m", map[string]string{"k": "v"}, 2},
383			{"m", map[string]string{"k": " v"}, 3},
384			{"m", map[string]string{"k": "v "}, 4},
385			{"m", map[string]string{" k": "v"}, 5},
386		}
387		for i, c := range cases {
388			var line string
389			if c.name == "m" {
390				line = queryLabels("m", 0, 10, c.labels)
391			} else {
392				line = `{"op":"query","name":` + jsonString(c.name) + `,"start":0,"end":10,"labels":` + jsonLabels(c.labels) + `}`
393			}
394			got := queryOne(t, store, line)
395			if got.Name != c.name || !reflect.DeepEqual(got.Labels, c.labels) || got.Average != c.value {
396				t.Fatalf("whitespace case %d: got %+v, want name=%q labels=%v value=%v", i, got, c.name, c.labels, c.value)
397			}
398		}
399		// 省略标签与空标签对象同一身份；缺标签与标签存在且值为空串仍是不同身份，
400		// 即使标签键周围带有合法空格。
401		mustOK(t, store, `[{"name":"n","timestamp":1,"value":1}]`)
402		if dup := mustOK(t, store, `[{"name":"n","timestamp":1,"value":1.0,"labels":{}}]`); dup.Added != 0 || dup.Duplicates != 1 {
403			t.Fatalf("omitted vs empty labels must be the same series, got %+v", dup)
404		}
405		if added := mustOK(t, store, `[{"name":"n","timestamp":1,"value":2,"labels":{" z ":""}}]`); added.Added != 1 {
406			t.Fatalf("missing label differs from present empty value, added = %d", added.Added)
407		}
408		// 快照中 n 现在有两条独立序列：无标签与带空值标签（连同 m 的五条共七条）。
409		nSeries := 0
410		for _, v := range mustOK(t, store, `[]`).Series {
411			if v.Name == "n" {
412				nSeries++
413			}
414		}
415		if nSeries != 2 {
416			t.Fatalf("metric n must have 2 distinct series, got %d", nSeries)
417		}
418		got := queryOne(t, store, queryLabels("n", 0, 10, map[string]string{" z ": ""}))
419		if len(got.Labels) != 1 || got.Labels[" z "] != "" || got.Average != 2 {
420			t.Fatalf("spaced-key empty-value label not preserved: %+v", got)
421		}
422	}
423	
424	// TestConflictMessageDistinguishesLookAlikeSeries 是任务场景的核心回归：
425	// cpu 的 {"a":"1,b=2"} 与 {"a":"1","b":"2"} 是两条不同序列，都在时间戳 1000
426	// 存有值 1；分别提交同时间戳的值 2 时，两条冲突原因的身份部分必须不同，
427	// 用户只看 error 字符串就能分辨冲突属于哪条真实序列。
428	func TestConflictMessageDistinguishesLookAlikeSeries(t *testing.T) {
429		store := NewMetricStore()
430		mustOK(t, store, `[
431			{"name":"cpu","timestamp":1000,"value":1,"labels":{"a":"1,b=2"}},
432			{"name":"cpu","timestamp":1000,"value":1,"labels":{"a":"1","b":"2"}}
433		]`)
434		single := mustFail(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"a":"1,b=2"}}]`)
435		if want := `conflict: series cpu{a="1,b=2"} at timestamp 1000 already has value 1, submitted 2`; single.Error != want {
436			t.Fatalf("single-label conflict = %q, want %q", single.Error, want)
437		}
438		pair := mustFail(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"a":"1","b":"2"}}]`)
439		if want := `conflict: series cpu{a=1,b=2} at timestamp 1000 already has value 1, submitted 2`; pair.Error != want {
440			t.Fatalf("two-label conflict = %q, want %q", pair.Error, want)
441		}
442		// 同一批次内两个不同值撞上同一采样点：身份渲染相同规则，原值取批内较早
443		// 出现的点，失败位置指向造成冲突的采样点；整批新增点不提交。
444		inBatch := mustFail(t, store, `[
445			{"name":"cpu","timestamp":2000,"value":3,"labels":{"a":"1,b=2"}},
446			{"name":"cpu","timestamp":2000,"value":4,"labels":{"a":"1,b=2"}}
447		]`)
448		if inBatch.Index != 2 {
449			t.Fatalf("in-batch conflict index = %d, want 2", inBatch.Index)
450		}
451		if want := `conflict: series cpu{a="1,b=2"} at timestamp 2000 already has value 3, submitted 4`; inBatch.Error != want {
452			t.Fatalf("in-batch conflict = %q, want %q", inBatch.Error, want)
453		}
454		if inBatch.Conflict == nil || inBatch.Conflict.Timestamp != 2000 ||
455			inBatch.Conflict.Existing != 3 || inBatch.Conflict.Submitted != 4 {
456			t.Fatalf("in-batch conflict detail = %+v", inBatch.Conflict)
457		}
458		for _, s := range mustOK(t, store, `[]`).Series {
459			for _, p := range s.Points {
460				if p.Timestamp == 2000 {
461					t.Fatalf("rejected batch must not commit, found %+v in %v", p, s.Labels)
462				}
463			}
464		}
465		// 此前成功写入的点保持原值。
466		for _, s := range mustQuery(t, store, `{"op":"query","name":"cpu","start":1000,"end":1000}`).Series {
467			if s.Count != 1 || s.Average != 1 {
468				t.Fatalf("stored point of %v must stay 1, got count=%d average=%v", s.Labels, s.Count, s.Average)
469			}
470		}
471	}
472	
473	// TestConflictMessageIdentityIndependentOfOrderAndEscapes：同一真实身份无论标签
474	// 在输入中如何排列、同一字符直接书写还是以合法 JSON 转义书写，冲突原因里的
475	// 身份部分都相同，标签仍按键排序展示。
476	func TestConflictMessageIdentityIndependentOfOrderAndEscapes(t *testing.T) {
477		store := NewMetricStore()
478		mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":1,"labels":{"a":"1,b=2","b":"x"}}]`)
479		want := `conflict: series cpu{a="1,b=2",b=x} at timestamp 1000 already has value 1, submitted 2`
480		// 标签顺序调换。
481		if lerr := mustFail(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"b":"x","a":"1,b=2"}}]`); lerr.Error != want {
482			t.Fatalf("reordered-labels conflict = %q, want %q", lerr.Error, want)
483		}
484		// 值里的逗号与等号改用 \u002C、\u003D 两个 JSON 转义书写，解析后身份相同，渲染也相同。
485		escaped := `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"a":"1` + uescape("002c") + `b` + uescape("003d") + `2","b":"x"}}]`
486		if lerr := mustFail(t, store, escaped); lerr.Error != want {
487			t.Fatalf("escaped-labels conflict = %q, want %q", lerr.Error, want)
488		}
489	}
490	
491	// TestConflictMessageRendersControlAndEdgeWhitespace：名称或标签中的换行与制表符
492	// 在冲突原因里呈现为 \n、\t 文字标记（一条原因仍是一条记录，不含原始控制字符）；
493	// 首尾空格与空字符串值以引号边界呈现，无标签与空值标签的渲染明确区分。
494	func TestConflictMessageRendersControlAndEdgeWhitespace(t *testing.T) {
495		store := NewMetricStore()
496		mustOK(t, store, `[{"name":"cp\nu","timestamp":1,"value":1,"labels":{" sp ":"","ho st":"a\tb","k":" v "}}]`)
497		// 标签顺序调换后身份相同；渲染按键排序，控制字符呈现为转义标记。
498		lerr := mustFail(t, store, `[{"name":"cp\nu","timestamp":1,"value":2,"labels":{"k":" v ","ho st":"a\tb"," sp ":""}}]`)
499		want := `conflict: series "cp\nu"{" sp "="",ho st="a\tb",k=" v "} at timestamp 1 already has value 1, submitted 2`
500		if lerr.Error != want {
501			t.Fatalf("conflict = %q, want %q", lerr.Error, want)
502		}
503		if strings.ContainsAny(lerr.Error, "\n\t") {
504			t.Fatalf("conflict message must not contain raw control characters: %q", lerr.Error)
505		}
506		// 结构化 conflict 中的名称与标签保持解析后的真实内容，不受渲染影响。
507		if lerr.Conflict.Series.Name != "cp\nu" ||
508			!reflect.DeepEqual(lerr.Conflict.Series.Labels, map[string]string{" sp ": "", "ho st": "a\tb", "k": " v "}) {
509			t.Fatalf("structured conflict must keep verbatim identity, got %+v", lerr.Conflict.Series)
510		}
511	
512		// 无标签与存在空字符串值标签是不同序列，冲突原因里 {} 与 k="" 明确区分。
513		mustOK(t, store, `[
514			{"name":"n","timestamp":1,"value":1},
515			{"name":"n","timestamp":1,"value":1,"labels":{"k":""}}
516		]`)
517		bare := mustFail(t, store, `[{"name":"n","timestamp":1,"value":2}]`)
518		if !strings.Contains(bare.Error, "series n{} at timestamp 1") {
519			t.Fatalf("no-label conflict = %q", bare.Error)
520		}
521		emptyVal := mustFail(t, store, `[{"name":"n","timestamp":1,"value":2,"labels":{"k":""}}]`)
522		if !strings.Contains(emptyVal.Error, `series n{k=""} at timestamp 1`) {
523			t.Fatalf("empty-value conflict = %q", emptyVal.Error)
524		}
525	}
526	
527	// TestConflictMessagePlainIdentityUnchanged：不含特殊字符的现有说明保留原样，
528	// 名称、键、值都不加引号。
529	func TestConflictMessagePlainIdentityUnchanged(t *testing.T) {
530		store := NewMetricStore()
531		mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":1,"labels":{"host":"a","zone":"east"}}]`)
532		lerr := mustFail(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a","zone":"east"}}]`)
533		want := "conflict: series cpu{host=a,zone=east} at timestamp 1000 already has value 1, submitted 2"
534		if lerr.Error != want {
535			t.Fatalf("plain conflict = %q, want %q", lerr.Error, want)
536		}
537	}
538	
539	// TestDelimiterLabelSubsetMatching：子集匹配按真实键值对进行，值里的分隔符既不会
540	// 制造额外的匹配标签，也不会让需要的标签匹配失败；不同序列的点不混合。
541	func TestDelimiterLabelSubsetMatching(t *testing.T) {
542		store := NewMetricStore()
543		mustOK(t, store, `[
544			{"name":"m","timestamp":1,"value":10,"labels":{"a":"x","b":"y=z"}},
545			{"name":"m","timestamp":1,"value":20,"labels":{"a":"x","b":"q"}},
546			{"name":"m","timestamp":1,"value":30,"labels":{"a":"x","b":"y=z","c":"d,e"}}
547		]`)
548		// a=x 子集命中三条，各自独立返回自己的点与均值。
549		res := mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"a": "x"}))
550		if len(res.Series) != 3 {
551			t.Fatalf("a=x subset = %+v, want 3 series", res.Series)
552		}
553		// b="y=z" 只命中真实拥有该键值的两条（含带额外标签 c 的一条），不命中 b=q。
554		res = mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"b": "y=z"}))
555		if len(res.Series) != 2 {
556			t.Fatalf("b=y=z subset = %+v, want 2 series", res.Series)
557		}
558		wantAvgs := map[int]bool{10: false, 30: false}
559		for _, s := range res.Series {
560			if s.Count != 1 {
561				t.Fatalf("matched series %v must report its own single point, got count=%d", s.Labels, s.Count)
562			}
563			if _, ok := wantAvgs[int(s.Average)]; !ok {
564				t.Fatalf("unexpected average %v from %v", s.Average, s.Labels)
565			}
566			wantAvgs[int(s.Average)] = true
567		}
568		for v, seen := range wantAvgs {
569			if !seen {
570				t.Fatalf("series with average %d was not matched separately", v)
571			}
572		}
573		// 查询值里写逗号文本是完整值比较：只有值恰好为 "d,e" 的标签能匹配。
574		if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"c": "d,e"})); got.Average != 30 {
575			t.Fatalf("comma-in-value subset = %+v, want average 30", got)
576		}
577		if len(mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"d": "e"})).Series) != 0 {
578			t.Fatalf("value fragment d,e must not be split into label d=e")
579		}
580	}
